Lemma chsh_abs_C_form : forall c, chsh_abs_C_256 c =
  if (if bool_dec (hw_bool_neq (hw_chsh_sign00 c) (hw_chsh_sign01 c))
                  (hw_bool_neq (hw_chsh_sign10 c) (hw_chsh_sign11 c)) then true else false)
  then wplus (hw_chsh_abs_C1 c) (hw_chsh_abs_C2 c) else hw_absdiffw (hw_chsh_abs_C1 c) (hw_chsh_abs_C2 c).
Proof. intro c. kernel_refl. Qed.

Lemma chsh_abs_A_form : forall c, chsh_abs_A_256 c =
  hw_absdiffw (hw_chsh_A_pos c) (wplus (hw_chsh_A_neg_a c) (hw_chsh_A_neg_b c)).
Proof. intro c. kernel_refl. Qed.

Lemma chsh_abs_B_form : forall c, chsh_abs_B_256 c =
  hw_absdiffw (hw_chsh_B_pos c) (wplus (hw_chsh_B_neg_a c) (hw_chsh_B_neg_b c)).
Proof. intro c. kernel_refl. Qed.

Lemma chsh_final_form : forall c, chsh_final_ok c =
  andb (andb (andb (andb (andb (andb (negb (hw_eqb (hw_chsh_n00 c) (natToWord 64 0)))
                                      (negb (hw_eqb (hw_chsh_n01 c) (natToWord 64 0))))
                                (negb (hw_eqb (hw_chsh_n10 c) (natToWord 64 0))))
                          (negb (hw_eqb (hw_chsh_n11 c) (natToWord 64 0))))
                    (negb (hw_ltb (hw_chsh_A_pos c) (wplus (hw_chsh_A_neg_a c) (hw_chsh_A_neg_b c)))))
              (negb (hw_ltb (hw_chsh_B_pos c) (wplus (hw_chsh_B_neg_a c) (hw_chsh_B_neg_b c)))))
       (negb (hw_ltb (hw_chsh_A_times_B c) (hw_chsh_C_sq c))).
Proof. intro c. kernel_refl. Qed.

Theorem chsh_run_result : forall b, hw_chsh_phase b = natToWord 5 1 ->
  (forall m, (m <= 22)%nat -> hw_chsh_phase (chsh_iter m b) = natToWord 5 (S m)) /\
  hw_chsh_phase (chsh_iter 23 b) = natToWord 5 0 /\
  hw_chsh_check_result (chsh_iter 23 b) = chsh_check_word_hw (hw_chsh_n00 b) (hw_chsh_n01 b) (hw_chsh_n10 b) (hw_chsh_n11 b) (hw_chsh_d00 b) (hw_chsh_d01 b) (hw_chsh_d10 b) (hw_chsh_d11 b) (hw_chsh_sign00 b) (hw_chsh_sign01 b) (hw_chsh_sign10 b) (hw_chsh_sign11 b) /\
  hw_pc (chsh_iter 23 b) = (if negb (chsh_check_word_hw (hw_chsh_n00 b) (hw_chsh_n01 b) (hw_chsh_n10 b) (hw_chsh_n11 b) (hw_chsh_d00 b) (hw_chsh_d01 b) (hw_chsh_d10 b) (hw_chsh_d11 b) (hw_chsh_sign00 b) (hw_chsh_sign01 b) (hw_chsh_sign10 b) (hw_chsh_sign11 b)) then hw_trap_vector b else hw_pc b) /\
  hw_err (chsh_iter 23 b) = (if negb (chsh_check_word_hw (hw_chsh_n00 b) (hw_chsh_n01 b) (hw_chsh_n10 b) (hw_chsh_n11 b) (hw_chsh_d00 b) (hw_chsh_d01 b) (hw_chsh_d10 b) (hw_chsh_d11 b) (hw_chsh_sign00 b) (hw_chsh_sign01 b) (hw_chsh_sign10 b) (hw_chsh_sign11 b)) then true else hw_err b) /\
  hw_error_code (chsh_iter 23 b) = (if negb (chsh_check_word_hw (hw_chsh_n00 b) (hw_chsh_n01 b) (hw_chsh_n10 b) (hw_chsh_n11 b) (hw_chsh_d00 b) (hw_chsh_d01 b) (hw_chsh_d10 b) (hw_chsh_d11 b) (hw_chsh_sign00 b) (hw_chsh_sign01 b) (hw_chsh_sign10 b) (hw_chsh_sign11 b)) then ERR_LOGIC_VAL else hw_error_code b).
Proof.
  intros b Ph0.
  assert (Ph1 : hw_chsh_phase (chsh_iter 1 b) = natToWord 5 2)
    by (change (chsh_iter 1 b) with (chsh_next (chsh_iter 0 b)); exact (chsh_phase1_chsh_phase (chsh_iter 0 b) Ph0)).
  assert (Ph2 : hw_chsh_phase (chsh_iter 2 b) = natToWord 5 3)
    by (change (chsh_iter 2 b) with (chsh_next (chsh_iter 1 b)); exact (chsh_phase2_chsh_phase (chsh_iter 1 b) Ph1)).
  assert (Ph3 : hw_chsh_phase (chsh_iter 3 b) = natToWord 5 4)
    by (change (chsh_iter 3 b) with (chsh_next (chsh_iter 2 b)); exact (chsh_phase3_chsh_phase (chsh_iter 2 b) Ph2)).
  assert (Ph4 : hw_chsh_phase (chsh_iter 4 b) = natToWord 5 5)
    by (change (chsh_iter 4 b) with (chsh_next (chsh_iter 3 b)); exact (chsh_phase4_chsh_phase (chsh_iter 3 b) Ph3)).
  assert (Ph5 : hw_chsh_phase (chsh_iter 5 b) = natToWord 5 6)
    by (change (chsh_iter 5 b) with (chsh_next (chsh_iter 4 b)); exact (chsh_phase5_chsh_phase (chsh_iter 4 b) Ph4)).
  assert (Ph6 : hw_chsh_phase (chsh_iter 6 b) = natToWord 5 7)
    by (change (chsh_iter 6 b) with (chsh_next (chsh_iter 5 b)); exact (chsh_phase6_chsh_phase (chsh_iter 5 b) Ph5)).
  assert (Ph7 : hw_chsh_phase (chsh_iter 7 b) = natToWord 5 8)
    by (change (chsh_iter 7 b) with (chsh_next (chsh_iter 6 b)); exact (chsh_phase7_chsh_phase (chsh_iter 6 b) Ph6)).
  assert (Ph8 : hw_chsh_phase (chsh_iter 8 b) = natToWord 5 9)
    by (change (chsh_iter 8 b) with (chsh_next (chsh_iter 7 b)); exact (chsh_phase8_chsh_phase (chsh_iter 7 b) Ph7)).
  assert (Ph9 : hw_chsh_phase (chsh_iter 9 b) = natToWord 5 10)
    by (change (chsh_iter 9 b) with (chsh_next (chsh_iter 8 b)); exact (chsh_phase9_chsh_phase (chsh_iter 8 b) Ph8)).
  assert (Ph10 : hw_chsh_phase (chsh_iter 10 b) = natToWord 5 11)
    by (change (chsh_iter 10 b) with (chsh_next (chsh_iter 9 b)); exact (chsh_phase10_chsh_phase (chsh_iter 9 b) Ph9)).
  assert (Ph11 : hw_chsh_phase (chsh_iter 11 b) = natToWord 5 12)
    by (change (chsh_iter 11 b) with (chsh_next (chsh_iter 10 b)); exact (chsh_phase11_chsh_phase (chsh_iter 10 b) Ph10)).
  assert (Ph12 : hw_chsh_phase (chsh_iter 12 b) = natToWord 5 13)
    by (change (chsh_iter 12 b) with (chsh_next (chsh_iter 11 b)); exact (chsh_phase12_chsh_phase (chsh_iter 11 b) Ph11)).
  assert (Ph13 : hw_chsh_phase (chsh_iter 13 b) = natToWord 5 14)
    by (change (chsh_iter 13 b) with (chsh_next (chsh_iter 12 b)); exact (chsh_phase13_chsh_phase (chsh_iter 12 b) Ph12)).
  assert (Ph14 : hw_chsh_phase (chsh_iter 14 b) = natToWord 5 15)
    by (change (chsh_iter 14 b) with (chsh_next (chsh_iter 13 b)); exact (chsh_phase14_chsh_phase (chsh_iter 13 b) Ph13)).
  assert (Ph15 : hw_chsh_phase (chsh_iter 15 b) = natToWord 5 16)
    by (change (chsh_iter 15 b) with (chsh_next (chsh_iter 14 b)); exact (chsh_phase15_chsh_phase (chsh_iter 14 b) Ph14)).
  assert (Ph16 : hw_chsh_phase (chsh_iter 16 b) = natToWord 5 17)
    by (change (chsh_iter 16 b) with (chsh_next (chsh_iter 15 b)); exact (chsh_phase16_chsh_phase (chsh_iter 15 b) Ph15)).
  assert (Ph17 : hw_chsh_phase (chsh_iter 17 b) = natToWord 5 18)
    by (change (chsh_iter 17 b) with (chsh_next (chsh_iter 16 b)); exact (chsh_phase17_chsh_phase (chsh_iter 16 b) Ph16)).
  assert (Ph18 : hw_chsh_phase (chsh_iter 18 b) = natToWord 5 19)
    by (change (chsh_iter 18 b) with (chsh_next (chsh_iter 17 b)); exact (chsh_phase18_chsh_phase (chsh_iter 17 b) Ph17)).
  assert (Ph19 : hw_chsh_phase (chsh_iter 19 b) = natToWord 5 20)
    by (change (chsh_iter 19 b) with (chsh_next (chsh_iter 18 b)); exact (chsh_phase19_chsh_phase (chsh_iter 18 b) Ph18)).
  assert (Ph20 : hw_chsh_phase (chsh_iter 20 b) = natToWord 5 21)
    by (change (chsh_iter 20 b) with (chsh_next (chsh_iter 19 b)); exact (chsh_phase20_chsh_phase (chsh_iter 19 b) Ph19)).
  assert (Ph21 : hw_chsh_phase (chsh_iter 21 b) = natToWord 5 22)
    by (change (chsh_iter 21 b) with (chsh_next (chsh_iter 20 b)); exact (chsh_phase21_chsh_phase (chsh_iter 20 b) Ph20)).
  assert (Ph22 : hw_chsh_phase (chsh_iter 22 b) = natToWord 5 23)
    by (change (chsh_iter 22 b) with (chsh_next (chsh_iter 21 b)); exact (chsh_phase22_chsh_phase (chsh_iter 21 b) Ph21)).
  assert (Ph23 : hw_chsh_phase (chsh_iter 23 b) = natToWord 5 0)
    by (change (chsh_iter 23 b) with (chsh_next (chsh_iter 22 b)); exact (chsh_phase23_chsh_phase (chsh_iter 22 b) Ph22)).
  assert (V_pc_0 : hw_pc (chsh_iter 0 b) = hw_pc b) by reflexivity.
  assert (V_pc_1 : hw_pc (chsh_iter 1 b) = hw_pc b)
    by (change (chsh_iter 1 b) with (chsh_next (chsh_iter 0 b)); rewrite (chsh_phase1_pc (chsh_iter 0 b) Ph0); exact V_pc_0).
  assert (V_pc_2 : hw_pc (chsh_iter 2 b) = hw_pc b)
    by (change (chsh_iter 2 b) with (chsh_next (chsh_iter 1 b)); rewrite (chsh_phase2_pc (chsh_iter 1 b) Ph1); exact V_pc_1).
  assert (V_pc_3 : hw_pc (chsh_iter 3 b) = hw_pc b)
    by (change (chsh_iter 3 b) with (chsh_next (chsh_iter 2 b)); rewrite (chsh_phase3_pc (chsh_iter 2 b) Ph2); exact V_pc_2).
  assert (V_pc_4 : hw_pc (chsh_iter 4 b) = hw_pc b)
    by (change (chsh_iter 4 b) with (chsh_next (chsh_iter 3 b)); rewrite (chsh_phase4_pc (chsh_iter 3 b) Ph3); exact V_pc_3).
  assert (V_pc_5 : hw_pc (chsh_iter 5 b) = hw_pc b)
    by (change (chsh_iter 5 b) with (chsh_next (chsh_iter 4 b)); rewrite (chsh_phase5_pc (chsh_iter 4 b) Ph4); exact V_pc_4).
  assert (V_pc_6 : hw_pc (chsh_iter 6 b) = hw_pc b)
    by (change (chsh_iter 6 b) with (chsh_next (chsh_iter 5 b)); rewrite (chsh_phase6_pc (chsh_iter 5 b) Ph5); exact V_pc_5).
  assert (V_pc_7 : hw_pc (chsh_iter 7 b) = hw_pc b)
    by (change (chsh_iter 7 b) with (chsh_next (chsh_iter 6 b)); rewrite (chsh_phase7_pc (chsh_iter 6 b) Ph6); exact V_pc_6).
  assert (V_pc_8 : hw_pc (chsh_iter 8 b) = hw_pc b)
    by (change (chsh_iter 8 b) with (chsh_next (chsh_iter 7 b)); rewrite (chsh_phase8_pc (chsh_iter 7 b) Ph7); exact V_pc_7).
