  assert (V_pc_10 : hw_pc (chsh_iter 10 b) = hw_pc b)
    by (change (chsh_iter 10 b) with (chsh_next (chsh_iter 9 b)); rewrite (chsh_phase10_pc (chsh_iter 9 b) Ph9); exact V_pc_9).
  assert (V_pc_11 : hw_pc (chsh_iter 11 b) = hw_pc b)
    by (change (chsh_iter 11 b) with (chsh_next (chsh_iter 10 b)); rewrite (chsh_phase11_pc (chsh_iter 10 b) Ph10); exact V_pc_10).
  assert (V_pc_12 : hw_pc (chsh_iter 12 b) = hw_pc b)
    by (change (chsh_iter 12 b) with (chsh_next (chsh_iter 11 b)); rewrite (chsh_phase12_pc (chsh_iter 11 b) Ph11); exact V_pc_11).
  assert (V_pc_13 : hw_pc (chsh_iter 13 b) = hw_pc b)
    by (change (chsh_iter 13 b) with (chsh_next (chsh_iter 12 b)); rewrite (chsh_phase13_pc (chsh_iter 12 b) Ph12); exact V_pc_12).
  assert (V_pc_14 : hw_pc (chsh_iter 14 b) = hw_pc b)
    by (change (chsh_iter 14 b) with (chsh_next (chsh_iter 13 b)); rewrite (chsh_phase14_pc (chsh_iter 13 b) Ph13); exact V_pc_13).
  assert (V_pc_15 : hw_pc (chsh_iter 15 b) = hw_pc b)
    by (change (chsh_iter 15 b) with (chsh_next (chsh_iter 14 b)); rewrite (chsh_phase15_pc (chsh_iter 14 b) Ph14); exact V_pc_14).
  assert (V_pc_16 : hw_pc (chsh_iter 16 b) = hw_pc b)
    by (change (chsh_iter 16 b) with (chsh_next (chsh_iter 15 b)); rewrite (chsh_phase16_pc (chsh_iter 15 b) Ph15); exact V_pc_15).
  assert (V_pc_17 : hw_pc (chsh_iter 17 b) = hw_pc b)
    by (change (chsh_iter 17 b) with (chsh_next (chsh_iter 16 b)); rewrite (chsh_phase17_pc (chsh_iter 16 b) Ph16); exact V_pc_16).
  assert (V_pc_18 : hw_pc (chsh_iter 18 b) = hw_pc b)
    by (change (chsh_iter 18 b) with (chsh_next (chsh_iter 17 b)); rewrite (chsh_phase18_pc (chsh_iter 17 b) Ph17); exact V_pc_17).
  assert (V_pc_19 : hw_pc (chsh_iter 19 b) = hw_pc b)
    by (change (chsh_iter 19 b) with (chsh_next (chsh_iter 18 b)); rewrite (chsh_phase19_pc (chsh_iter 18 b) Ph18); exact V_pc_18).
  assert (V_pc_20 : hw_pc (chsh_iter 20 b) = hw_pc b)
    by (change (chsh_iter 20 b) with (chsh_next (chsh_iter 19 b)); rewrite (chsh_phase20_pc (chsh_iter 19 b) Ph19); exact V_pc_19).
  assert (V_pc_21 : hw_pc (chsh_iter 21 b) = hw_pc b)
    by (change (chsh_iter 21 b) with (chsh_next (chsh_iter 20 b)); rewrite (chsh_phase21_pc (chsh_iter 20 b) Ph20); exact V_pc_20).
  assert (V_pc_22 : hw_pc (chsh_iter 22 b) = hw_pc b)
    by (change (chsh_iter 22 b) with (chsh_next (chsh_iter 21 b)); rewrite (chsh_phase22_pc (chsh_iter 21 b) Ph21); exact V_pc_21).
  assert (V_err_0 : hw_err (chsh_iter 0 b) = hw_err b) by reflexivity.
  assert (V_err_1 : hw_err (chsh_iter 1 b) = hw_err b)
    by (change (chsh_iter 1 b) with (chsh_next (chsh_iter 0 b)); rewrite (chsh_phase1_err (chsh_iter 0 b) Ph0); exact V_err_0).
  assert (V_err_2 : hw_err (chsh_iter 2 b) = hw_err b)
    by (change (chsh_iter 2 b) with (chsh_next (chsh_iter 1 b)); rewrite (chsh_phase2_err (chsh_iter 1 b) Ph1); exact V_err_1).
  assert (V_err_3 : hw_err (chsh_iter 3 b) = hw_err b)
